'use strict';
if(document.documentElement.dataset.hosting==='cloud'){
 const config=window.DamDaCloudConfig;
 const client=config?.url&&config?.key?supabase.createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce',storageKey:'damda-auth-'+new URL(config.url).hostname}}):null;
 const defaultProfile=user=>({name:user.user_metadata?.display_name||'',nickname:'',nameMode:'name',showName:true,theme:'blue',photo:'',photoShape:'rounded',photoSize:'medium',back:{title:'Nice to meet you.',message:'',color:'blue',pattern:'orbits'},fields:['직업','회사','이메일','전화번호','Instagram','취미','Discord'].map(label=>({label,value:label==='이메일'?user.email||'':'',selected:label==='이메일'}))});
 const freshOrganizer=()=>DamDaOrganizer.create({getItem:()=>null,setItem(){}}).read();
 const baseRenderCloud=render,baseDecorateCloud=decorate;
 let currentUser=null,state=null,dirty=false,saveTimer=null,saving=null,saveError='',loadError='',loading=true,authBusy=false,epoch=0,version=0,recovery=false,notice='';
 const baseURL=()=>location.origin+location.pathname;
 const authMessage=e=>({invalid_credentials:'이메일 또는 비밀번호를 확인해 주세요.',email_not_confirmed:'이 계정은 이메일 미인증 상태예요. 관리자에게 이메일 확인 설정과 계정 상태를 확인해 주세요.',user_already_exists:'이미 가입된 이메일이에요. 로그인해 주세요.',over_email_send_rate_limit:'이메일 요청이 많아요. 잠시 후 다시 시도해 주세요.',over_request_rate_limit:'요청이 많아요. 잠시 후 다시 시도해 주세요.',weak_password:'더 안전한 비밀번호를 사용해 주세요.',same_password:'현재 비밀번호와 다른 비밀번호를 입력해 주세요.'}[e?.code]||'요청을 처리하지 못했어요. 잠시 후 다시 시도해 주세요.');

 function passwordInfo(value){const types=[/[A-Z]/,/[a-z]/,/[0-9]/,/[^A-Za-z0-9\s]/].filter(re=>re.test(value)).length;const valid=value.length>=8&&types>=2;return {types,valid,level:!valid?1:value.length>=12&&types>=3?3:2};}
 function passwordGuide(id){return '<div class="password-guide" id="'+id+'-guide" aria-live="polite"><strong data-strength>'+tr('비밀번호 강도: 입력 전','Password strength: not entered')+'</strong><div class="password-meter" aria-hidden="true"><span></span><span></span><span></span></div><p data-length>'+tr('8자 이상 필요','At least 8 characters required')+'</p><p data-types>'+tr('대문자·소문자·숫자·특수문자 중 2종류 이상 필요','Use at least 2 types: uppercase, lowercase, numbers, symbols')+'</p></div>';}
 function validatePassword(value){if(!passwordInfo(value).valid)throw {friendly:tr('비밀번호는 8자 이상이며 대문자·소문자·숫자·특수문자 중 2종류 이상을 포함해야 해요.','Use at least 8 characters and at least 2 character types.')};}
 app.addEventListener('input',e=>{if(!['signup-password','new-password'].includes(e.target.id))return;const value=e.target.value,info=passwordInfo(value),guide=document.getElementById(e.target.id+'-guide');if(!guide)return;guide.dataset.level=value?info.level:0;guide.querySelector('[data-strength]').textContent=tr('비밀번호 강도: ','Password strength: ')+(value?[tr('약함','Weak'),tr('중간','Medium'),tr('강력','Strong')][info.level-1]:tr('입력 전','Not entered'));guide.querySelector('[data-length]').textContent=(value.length>=8?'✓ ':'○ ')+tr('8자 이상','At least 8 characters');guide.querySelector('[data-types]').textContent=(info.types>=2?'✓ ':'○ ')+tr('대문자·소문자·숫자·특수문자 중 2종류 이상','At least 2 types: uppercase, lowercase, numbers, symbols')+' ('+info.types+'/4)';});
 const route=()=>location.hash.split('?')[0];
 function syncStatus(){const el=document.getElementById('cloud-save-status');if(el){el.textContent=saveError?tr('저장 실패 · 다시 저장','Save failed · Retry'):dirty||saving?tr('저장 중…','Saving…'):tr('계정에 저장됨','Saved to account');el.disabled=!!saving;el.dataset.failed=saveError?'true':'false';}}
 decorate=function(){baseDecorateCloud();const bar=app.querySelector('.damda-topbar');if(signedIn&&bar&&!document.getElementById('cloud-save-status'))bar.insertAdjacentHTML('beforeend','<button type="button" class="text-button" id="cloud-save-status" data-cloud="retry-save" aria-live="polite"></button>');syncStatus();};
 const shellCloud=workspaceShell;
 workspaceShell=function(page,content){return shellCloud(page,content.replaceAll(tr('이 브라우저에 저장됩니다. 다른 기기와 동기화되지 않아요.'),tr('내 계정에 저장되며 다른 기기에서도 확인할 수 있어요.','Saved to your account and available on other devices.')));};
 function dirtyState(){if(!currentUser||!state)return;dirty=true;version++;saveError='';clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(()=>{}),650);syncStatus();}
 window.DamDaCloudStore={saveProfile(value){if(currentUser&&state){state.profile=structuredClone(value);dirtyState();}}};
 async function flush(){
  clearTimeout(saveTimer);if(saving){await saving;if(dirty)return flush();return;}
  if(!dirty||!currentUser||!state)return;
  const capturedEpoch=epoch,userId=currentUser.id,capturedVersion=version,revision=state.revision;
  const document={profile:structuredClone(profile),organizer:structuredClone(state.organizer),revision:revision+1,updated_at:new Date().toISOString()};
  saving=(async()=>{const result=await client.from('damda_accounts').update(document).eq('user_id',userId).eq('revision',revision).select('revision').maybeSingle();
   if(capturedEpoch!==epoch)return;
   if(result.error)throw Error(tr('변경 내용을 저장하지 못했어요. 연결을 확인하고 다시 저장해 주세요.','Could not save changes. Check your connection and retry.'));
   if(!result.data)throw Error(tr('다른 기기에서 변경되었어요. 현재 내용을 복사한 뒤 새로고침해 주세요.','Changed on another device. Copy your edits, then reload.'));
   state.revision=result.data.revision;dirty=capturedVersion!==version;saveError='';
  })();syncStatus();
  try{await saving;}catch(e){if(capturedEpoch===epoch){saveError=e.message;notify(e.message);}throw e;}finally{saving=null;syncStatus();}
  if(dirty&&capturedEpoch===epoch)return flush();
 }
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 function clearAccount(){epoch++;clearTimeout(saveTimer);currentUser=null;state=null;dirty=false;saveError='';signedIn=false;selectedPreset='';presetDraft=null;bookTab='전체';activeShare=null;profile=defaultProfile({});organizer=DamDaOrganizer.create({getItem:()=>null,setItem(){throw Error('먼저 로그인해 주세요.');}});sessionStorage.removeItem('fold-profile');sessionStorage.removeItem('fold-session');}
 async function loadAccount(user){
  if(currentUser?.id===user.id&&state)return;
  clearAccount();const capturedEpoch=epoch;currentUser=user;loading=true;loadError='';render();
  try{
   let result=await client.from('damda_accounts').select('profile,organizer,revision').eq('user_id',user.id).maybeSingle();if(result.error)throw result.error;
   if(!result.data){const fresh={user_id:user.id,profile:defaultProfile(user),organizer:freshOrganizer(),revision:0};result=await client.from('damda_accounts').insert(fresh).select('profile,organizer,revision').single();if(result.error?.code==='23505')result=await client.from('damda_accounts').select('profile,organizer,revision').eq('user_id',user.id).single();if(result.error)throw result.error;}
   if(capturedEpoch!==epoch)return;
   state=result.data;profile={...defaultProfile(user),...state.profile};
   if(!Array.isArray(profile.fields)||!Array.isArray(state.organizer?.cards)||!Array.isArray(state.organizer?.tabs)||!Array.isArray(state.organizer?.presets))throw Error('invalid account');
   organizer=DamDaOrganizer.create({getItem:()=>JSON.stringify(state.organizer),setItem:(key,value)=>{state.organizer=JSON.parse(value);dirtyState();}});
   signedIn=true;loading=false;restorePresetSelection();
   if(!['#card','#book','#home'].includes(route())&&!recovery)location.hash='home';render();
  }catch{if(capturedEpoch!==epoch)return;state=null;signedIn=false;loading=false;loadError=tr('계정 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요.','Could not load your account. Please retry.');render();}
 }
 function authPage(content){return header()+'<main class="auth-layout">'+intro()+'<div class="form-panel">'+content+'</div></main>'+footer;}
 function errorBox(){return '<div id="form-error" role="alert">'+(notice?'<p class="hint">'+esc(notice)+'</p>':'')+'</div>';}
 loginView=function(){return '<div class="form-panel"><div class="kicker">WELCOME BACK</div><h2>'+tr('다시 만나 반가워요','Welcome back')+'</h2><p class="sub">'+tr('내 계정에 저장한 명함을 이어서 꾸며보세요.','Continue creating the cards saved to your account.')+'</p><form id="login-form">'+field(tr('이메일','Email'),'login-id','email','hello@example.com','','required autocomplete="username" maxlength="254"')+field(tr('비밀번호','Password'),'login-password','password',tr('비밀번호를 입력해 주세요.','Your password'),'','required autocomplete="current-password" maxlength="128"')+errorBox()+'<button type="submit" class="primary login-submit" '+(authBusy?'disabled':'')+'>'+tr('로그인','Sign in')+'</button></form><div class="row-between"><button type="button" class="text-button" data-cloud="forgot">'+tr('비밀번호 재설정','Reset password')+'</button></div><div class="signup-prompt">'+tr('처음 오셨나요?','New here?')+'<a href="#signup">'+tr('회원가입','Sign up')+'</a></div></div>';};
 signupView=function(){return '<div class="form-panel"><div class="kicker">A NEW CONNECTION</div><h2>'+tr('나를 잇는 첫걸음','Your first connection')+'</h2><p class="sub">'+tr('계정을 만들고 나만의 명함을 저장하세요.','Create an account to save your cards.')+'</p><form id="signup-form">'+field(tr('이름 또는 닉네임','Name or nickname'),'signup-name','text',tr('명함에 사용할 이름','Name for your card'),'','required maxlength="30" autocomplete="name"')+field(tr('이메일','Email'),'signup-email','email','hello@example.com','','required maxlength="254" autocomplete="email"')+field(tr('비밀번호','Password'),'signup-password','password',tr('8자 이상 · 2종류 이상 조합','At least 8 characters · 2 character types'),'','required minlength="8" maxlength="128" autocomplete="new-password"')+passwordGuide('signup-password')+field(tr('비밀번호 확인','Confirm password'),'confirm-password','password',tr('비밀번호를 한 번 더 입력해 주세요.','Repeat your password'),'','required minlength="8" maxlength="128" autocomplete="new-password"')+'<p class="policy">'+tr('이메일은 로그인 아이디로 사용합니다. 프로필과 명함함은 내 계정에 저장되며, 직접 공유한 명함만 링크를 통해 공개됩니다.','Your email is used to sign in. Your profile and collection are private; only cards you share are available by link.')+'</p><label class="check-label"><input type="checkbox" required>'+tr('계정 정보 저장 및 공개 범위를 확인했어요.','I understand how my account and shared cards are stored.')+'</label>'+errorBox()+'<button class="primary" type="submit" '+(authBusy?'disabled':'')+'>'+tr('가입하고 시작하기','Create account')+'</button></form><div class="signup-prompt">'+tr('이미 계정이 있나요?','Already have an account?')+'<a href="#login">'+tr('로그인','Sign in')+'</a></div></div>';};
 function recoveryPage(){return authPage('<h2>'+tr('새 비밀번호 설정','Set a new password')+'</h2><form id="cloud-recovery-form">'+field(tr('새 비밀번호','New password'),'new-password','password','','','required minlength="8" maxlength="128" autocomplete="new-password"')+passwordGuide('new-password')+field(tr('비밀번호 확인','Confirm password'),'new-password-confirm','password','','','required minlength="8" maxlength="128" autocomplete="new-password"')+errorBox()+'<button class="primary" type="submit">'+tr('비밀번호 변경','Change password')+'</button></form>');}
 render=function(){
  if(!client){app.innerHTML=authPage('<h2>서비스 연결 준비 중</h2><p class="sub">계정 서비스를 연결하고 있어요. 잠시 후 다시 방문해 주세요.</p>');decorate();return;}
  if(recovery){app.innerHTML=recoveryPage();decorate();return;}
  if(route()==='#card'){renderReceived();return;}
  if(loading){app.innerHTML=authPage('<p class="sub" role="status">'+tr('계정을 확인하고 있어요…','Checking your account…')+'</p>');decorate();return;}
  if(loadError){app.innerHTML=authPage('<h2>'+tr('계정 연결을 확인해 주세요','Check account connection')+'</h2><p role="alert">'+esc(loadError)+'</p><button class="primary" data-cloud="retry-load">'+tr('다시 시도','Retry')+'</button><button class="text-button" data-action="logout">'+tr('로그아웃','Sign out')+'</button>');decorate();return;}
  baseRenderCloud();
 };
 async function runAuth(form,action){if(authBusy)return;authBusy=true;const button=form?.querySelector('[type="submit"]');if(button)button.disabled=true;notice='';try{await action();}catch(e){const box=document.getElementById('form-error');if(box)box.innerHTML='<p class="error">'+esc(e.friendly||authMessage(e))+'</p>';else notify(e.friendly||authMessage(e));}finally{authBusy=false;if(button?.isConnected)button.disabled=false;app.querySelectorAll('#login-form [type="submit"],#signup-form [type="submit"],#cloud-recovery-form [type="submit"]').forEach(b=>b.disabled=false);}}
 app.addEventListener('submit',e=>{
  if(!['login-form','signup-form','cloud-recovery-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const form=e.target;
  if(!client)return;
  runAuth(form,async()=>{
   if(form.id==='login-form'){const result=await client.auth.signInWithPassword({email:document.getElementById('login-id').value.trim(),password:document.getElementById('login-password').value});if(result.error)throw result.error;await loadAccount(result.data.user);}
   if(form.id==='signup-form'){
    const password=document.getElementById('signup-password').value;validatePassword(password);if(password!==document.getElementById('confirm-password').value)throw {friendly:tr('비밀번호가 일치하지 않아요.','Passwords do not match.')};
    const result=await client.auth.signUp({email:document.getElementById('signup-email').value.trim(),password,options:{data:{display_name:document.getElementById('signup-name').value.trim()}}});if(result.error)throw result.error;
    if(result.data.session)await loadAccount(result.data.user);else{notice=tr('가입 후 자동 로그인되지 않았어요. 기존 계정으로 로그인하거나 관리자에게 가입 설정을 확인해 주세요.','Automatic sign-in was unavailable. Sign in with an existing account or ask the administrator to check signup settings.');location.hash='login';render();}
   }
   if(form.id==='cloud-recovery-form'){const password=document.getElementById('new-password').value;validatePassword(password);if(password!==document.getElementById('new-password-confirm').value)throw {friendly:tr('비밀번호가 일치하지 않아요.','Passwords do not match.')};const result=await client.auth.updateUser({password});if(result.error)throw result.error;recovery=false;history.replaceState(null,'',location.pathname);notice=tr('비밀번호를 변경했어요.','Password updated.');await loadAccount(result.data.user);location.hash='home';render();notify(notice);}
  });
 },true);
 app.addEventListener('click',e=>{
  const button=e.target.closest('button');if(!button)return;
  if(button.dataset.action==='logout'){e.preventDefault();e.stopImmediatePropagation();runAuth(null,async()=>{await flush();const result=await client.auth.signOut();if(result.error)throw result.error;clearAccount();loadError='';loading=false;notice='';location.hash='login';render();});return;}
  if(['enter','fill-demo','help'].includes(button.dataset.action)){e.stopImmediatePropagation();return;}
  if(!button.dataset.cloud)return;e.preventDefault();e.stopImmediatePropagation();
  if(button.dataset.cloud==='retry-save'){flush().catch(()=>{});return;}
  if(button.dataset.cloud==='retry-load'){const user=currentUser;currentUser=null;if(user)loadAccount(user);return;}
  if(button.dataset.cloud==='forgot')runAuth(null,async()=>{const input=document.getElementById('login-id');if(!input?.value||!input.checkValidity())throw {friendly:tr('이메일을 먼저 입력해 주세요.','Enter your email first.')};const result=await client.auth.resetPasswordForEmail(input.value.trim(),{redirectTo:baseURL()+'?auth=recovery'});if(result.error)throw result.error;notice=tr('이메일을 확인해 주세요. 등록된 계정이라면 안내 메일이 도착합니다.','Check your email. Registered accounts will receive instructions.');document.getElementById('form-error').textContent=notice;});
 },true);
 // Share only the explicit public snapshot. The full profile never enters a shared row.
 share=async function(){if(sharePending||!signedIn||!currentUser)return;sharePending=true;const revision=shareRevision,userId=currentUser.id,capturedEpoch=epoch,data=selectedSnapshot(),button=app.querySelector('[data-action="share"]');if(button)button.disabled=true;
  try{if(!data.name&&!data.fields.length)throw Error(tr('공개할 정보를 하나 이상 선택해 주세요.','Choose at least one detail to share.'));await flush();const result=await client.from('damda_shared_cards').insert({owner_id:userId,data}).select('id').single();if(result.error)throw Error(tr('명함을 저장하지 못했어요. 다시 시도해 주세요.','Could not save your card. Please retry.'));if(capturedEpoch!==epoch||revision!==shareRevision)return;activeShare={id:result.data.id,url:baseURL()+'#card?id='+result.data.id};organizer.add(data,result.data.id);await flush();showShare();}catch(e){notify(e.message);}finally{sharePending=false;if(button?.isConnected)button.disabled=false;}
 };
 showShare=function(){const state=activeShare;if(!state)return;const panel=document.getElementById('share-result');if(!panel)return;panel.innerHTML='<section class="share-panel"><h3>'+tr('명함이 준비됐어요','Your card is ready')+'</h3><div class="qr-frame"><img id="share-qr" width="216" height="216" alt="'+tr('명함 공유 QR 코드','Card sharing QR')+'"></div><p id="qr-error" class="hint" role="status"></p><label for="share-url" class="network-label">'+tr('공유 링크','Share link')+'</label><div class="copy-row"><input id="share-url" readonly value="'+esc(state.url)+'"><button class="secondary" data-cloud-share="copy">'+tr('복사','Copy')+'</button></div><div class="share-actions"><a class="secondary" href="'+esc(state.url)+'" target="_blank" rel="noopener">'+tr('명함 열기','Open card')+'</a><a class="secondary" id="cloud-qr-download" download="DamDa-QR.png" hidden>'+tr('QR 저장 ↓','Save QR ↓')+'</a>'+(navigator.share?'<button class="secondary" data-cloud-share="native">'+tr('공유하기','Share')+'</button>':'')+'</div><p class="hint">'+tr('선택한 공개 정보와 뒷면이 저장됐어요. 링크를 아는 사람은 로그인 없이 볼 수 있어요.','Your selected details and card back are saved. Anyone with the link can view them without signing in.')+'</p></section>';DamDaQR.toDataURL(state.url,{width:600,margin:4,errorCorrectionLevel:'M'}).then(png=>{if(activeShare!==state||!panel.isConnected)return;panel.querySelector('#share-qr').src=png;const link=panel.querySelector('#cloud-qr-download');link.href=png;link.hidden=false;}).catch(()=>{if(panel.isConnected)panel.querySelector('#qr-error').textContent=tr('QR을 만들지 못했어요. 공유 링크를 이용해 주세요.','QR unavailable. Use the share link.');});};
 app.addEventListener('click',async e=>{const button=e.target.closest('[data-cloud-share]');if(!button||!activeShare)return;try{if(button.dataset.cloudShare==='native')await navigator.share({title:'DamDa',url:activeShare.url});else{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(activeShare.url);else{document.getElementById('share-url').select();if(!document.execCommand('copy'))throw Error('copy');}notify('명함 링크를 복사했어요.','Card link copied.');}}catch(e){if(e.name!=='AbortError')notify('공유 링크를 선택해 복사해 주세요.','Select and copy the share link.');}});
 receivedCardId=function(){return new URLSearchParams(location.hash.split('?')[1]).get('id')||'';};
 renderReceived=async function(){receivedCard=null;const requested=location.hash;app.innerHTML=header()+'<main class="shared"><p role="status">'+tr('명함을 불러오고 있어요…','Loading card…')+'</p></main>'+footer;decorate();try{const id=receivedCardId();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id))throw Error(tr('공유 주소를 다시 확인해 주세요.','Check the share link.'));const result=await client.rpc('damda_get_shared_card',{card_id:id});if(result.error||!result.data)throw Error(tr('명함을 찾을 수 없어요. 공유한 사람에게 새 링크를 요청해 주세요.','Card unavailable. Ask the sender for a new link.'));if(location.hash!==requested)return;const data=result.data;if(typeof data.name!=='string'||!Array.isArray(data.fields)||data.fields.length>20||!data.fields.every(f=>typeof f.label==='string'&&typeof f.value==='string')||(data.photo&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(data.photo)))throw Error(tr('명함 정보가 올바르지 않아요.','Invalid card data.'));receivedCard=data;app.innerHTML=header()+'<main class="shared"><div class="eyebrow">NICE TO MEET YOU</div><h1 class="received-title">'+tr('반가워요, 나의 명함이에요.','Nice to meet you. Here is my card.')+'</h1>'+card(data)+'<div class="download-actions"><button class="primary" data-action="download-png">'+tr('명함 이미지 저장 ↓','Save card image ↓')+'</button><button class="secondary" data-action="download-vcf">'+tr('연락처 저장 (VCF)','Save contact (VCF)')+'</button><button class="secondary" data-extra="save-received">'+tr('명함함에 저장','Save to collection')+'</button></div><a href="#login" class="received-cta">'+tr('나도 DamDa 명함 만들기','Create my DamDa card')+'</a></main>'+footer;}catch(e){if(location.hash!==requested)return;app.innerHTML=header()+'<main class="shared"><h2>'+tr('명함을 열 수 없어요','Could not open this card')+'</h2><p class="sub">'+esc(e.message)+'</p><a class="secondary" href="#login">'+tr('홈으로','Go home')+'</a></main>'+footer;}decorate();};
 clearAccount();render();
 if(client){client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{if(event==='PASSWORD_RECOVERY'){recovery=true;loading=false;render();return;}if(event==='SIGNED_OUT'){clearAccount();loadError='';loading=false;render();return;}if(event!=='INITIAL_SESSION'&&session?.user&&!recovery&&!authBusy&&!loading)loadAccount(session.user);},0);});client.auth.getSession().then(async result=>{if(result.error)throw result.error;if(result.data.session){const verified=await client.auth.getUser();if(verified.error)throw verified.error;recovery=new URLSearchParams(location.search).get('auth')==='recovery';if(recovery){loading=false;render();}else await loadAccount(verified.data.user);}else{loading=false;render();}}).catch(()=>{loading=false;notice=tr('로그인 상태를 확인하지 못했어요. 다시 로그인해 주세요.','Could not restore your session. Please sign in again.');render();});}
}
